css:
/* ========================================================================
   LIFE BRANCH EXPENDITURE — STYLED TO MATCH ACCOUNTS COMMAND CENTER
   Paste into Web Page > Style. Do NOT include <style> tags.
   Fonts, colors, sizes and spacing are aligned to the ACC standard.
   All #expApp IDs / classes are unchanged, so HTML + JS need no edits.

   NOTE: add this Google Fonts <link> once to the Web Page header (or a
   Custom HTML block on the page) so Archivo + Inter load:
   <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
   ======================================================================== */

:root {
  /* ACC green scale */
  --life-green-950: #0F3D1E;
  --life-green-900: #0F3D1E;
  --life-green-800: #14501F;
  --life-green-700: #1B5E20;
  --life-green-600: #2E7D32;
  --life-green-500: #43A047;
  --life-green-400: #66BB6A;
  --life-green-100: #E8F5E9;
  --life-green-50:  #F3FAF4;

  --life-border: #DCE9DE;
  --life-text:   #152418;
  --life-muted:  #5F6F63;

  /* ACC accent scale */
  --life-red:    #C62828;
  --life-redbg:  #FDECEA;
  --life-orange: #E65100;
  --life-amber:  #E65100;
  --life-blue:   #1565C0;
  --life-purple: #1565C0;

  --life-white: #ffffff;
  --life-shadow: 0 8px 26px rgba(15, 61, 30, .20);

  --disp: 'Archivo', system-ui, -apple-system, sans-serif;
  --body: 'Inter', system-ui, -apple-system, sans-serif;
}

/* Make the Frappe Web Page behave like a full dashboard. */
body:has(#expApp) {
  background: #F1F8F2;
}

body:has(#expApp) .page-header,
body:has(#expApp) .page-breadcrumbs,
body:has(#expApp) .web-footer,
body:has(#expApp) > header.navbar,
body:has(#expApp) > nav.navbar,
body:has(#expApp) .web-navbar,
body:has(#expApp) .navbar.navbar-expand-lg {
  display: none !important;
}

body:has(#expApp) .web-page-content,
body:has(#expApp) main,
body:has(#expApp) .page_content {
  padding-top: 0 !important;
}

body:has(#expApp) .web-page-content > .container,
body:has(#expApp) main > .container {
  max-width: 100% !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
}

#expApp,
#expApp * {
  box-sizing: border-box;
}

#expApp {
  width: calc(100vw - 32px);
  max-width: 1720px;
  position: relative;
  left: 50%;
  transform: translateX(-50%);
  margin: 0 auto 30px;
  color: var(--life-text);
  font-family: var(--body);
  font-size: 13px;
  line-height: 1.45;
  scroll-behavior: smooth;
}

#expApp button,
#expApp select,
#expApp input {
  font-family: var(--body);
}

/* ───────────────────────────── Hero Header (ACC .hdr) ───────────────── */
#expApp .life-exp-hero {
  /*min-height: 92px;*/
  /*padding: 16px 22px;*/
  /*border-radius: 0 0 18px 18px;*/
  /*background: linear-gradient(135deg, var(--life-green-900), var(--life-green-700) 65%, var(--life-green-600));*/
  /*display: flex;*/
  /*align-items: center;*/
  /*justify-content: space-between;*/
  /*gap: 20px;*/
  /*color: #fff;*/
  /*box-shadow: var(--life-shadow);*/
  /*margin-bottom: 14px;*/
  display:none;
}

#expApp .life-exp-brand {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

#expApp .life-exp-logo {
  width: 64px;
  min-width: 64px;
  height: 64px;
  border-radius: 14px;
  background: #fff;
  color: var(--life-green-800);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 16px rgba(0, 0, 0, .17);
  border: 1px solid rgba(255,255,255,.7);
}

#expApp .life-exp-logo-letter {
  color: var(--life-green-800);
  font-family: var(--disp);
  font-size: 38px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -2px;
}

/* Legacy logo bits stay hidden */
#expApp .life-exp-logo-word,
#expApp .life-exp-logo-tag,
#expApp .life-exp-tabs {
  display: none !important;
}

#expApp .life-exp-brand-copy { min-width: 0; }

#expApp .life-exp-brand-copy h1 {
  margin: 0;
  color: #fff;
  font-family: var(--disp);
  font-size: 16px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: 0;
}

#expApp .life-exp-brand-copy p {
  margin: 5px 0 0;
  color: #BFE3C4;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
}

/* Go to App button */
#expApp .life-exp-go-app-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-top: 11px;
  padding: 7px 15px;
  border: 1px solid rgba(255, 255, 255, .72);
  border-radius: 99px;
  background: #ffffff;
  color: var(--life-green-900);
  font-size: 11px;
  line-height: 1;
  font-weight: 700;
  text-decoration: none !important;
  box-shadow: 0 4px 12px rgba(0, 0, 0, .16);
  transition: transform .12s ease, background .12s ease, box-shadow .12s ease;
}

#expApp .life-exp-go-app-btn:hover,
#expApp .life-exp-go-app-btn:focus {
  background: var(--life-green-50);
  color: var(--life-green-900);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, .22);
  outline: none;
}

#expApp .life-exp-go-app-btn:active { transform: translateY(0); }

#expApp .life-exp-header-status {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

#expApp .life-exp-branch-pill,
#expApp .life-exp-clock-pill {
  min-height: 36px;
  padding: 7px 13px;
  border: 1px solid rgba(255,255,255,.24);
  border-radius: 99px;
  background: rgba(255,255,255,.14);
  backdrop-filter: blur(7px);
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

#expApp .life-exp-clock-pill {
  flex-direction: column;
  align-items: flex-end;
  gap: 0;
  line-height: 1.25;
}

#expApp .life-exp-clock-pill strong { font-size: 13px; }

#expApp .life-exp-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--life-green-400);
  box-shadow: 0 0 0 4px rgba(102, 187, 106, .18);
}

/* ───────────────────────────── Main Panels (ACC .card) ─────────────── */
#expApp .life-panel {
  margin: 0 0 13px;
  padding: 15px 17px;
  background: #fff;
  border: 1px solid var(--life-border);
  border-radius: 15px;
  box-shadow: 0 4px 14px rgba(15, 61, 30, .06);
}

#expApp .life-panel + .life-panel,
#expApp .expenditure-form + .life-panel,
#expApp .jebox + .life-panel {
  margin-top: 13px;
}

#expApp #expOverview {
  margin-top: 0;
  border-radius: 15px;
}

#expApp .life-section-head {
  margin-bottom: 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

#expApp .life-section-head h2 {
  margin: 0;
  color: var(--life-green-900);
  font-family: var(--disp);
  font-size: 13.5px;
  font-weight: 800;
}

#expApp .life-section-kicker {
  color: var(--life-green-600);
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .9px;
  text-transform: uppercase;
}

#expApp .life-cycle-badge {
  padding: 3px 9px;
  border: 1px solid #CDE8D1;
  border-radius: 99px;
  background: var(--life-green-100);
  color: var(--life-green-800);
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .3px;
}

/* ───────────────────────────── Filter Area ─────────────────────────── */
#expApp .topfilter {
  margin-bottom: 14px;
  padding: 14px 15px;
  border: 1px solid var(--life-border);
  border-radius: 14px;
  background: var(--life-green-50);
  display: grid;
  grid-template-columns: minmax(220px, 1.2fr) minmax(150px, .65fr) minmax(150px, .65fr) auto;
  gap: 12px;
  align-items: end;
}

#expApp .filter-field label {
  margin: 0 0 6px;
  display: block;
  color: var(--life-muted);
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .9px;
  text-transform: uppercase;
}

#expApp .fsel,
#expApp .finput {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1.5px solid var(--life-border);
  border-radius: 9px;
  outline: 0;
  background: #fff;
  color: var(--life-text);
  font-size: 12.5px;
  transition: .15s ease;
}

#expApp .fsel:focus,
#expApp .finput:focus {
  border-color: var(--life-green-500);
  box-shadow: 0 0 0 3px rgba(67,160,71,.12);
}

#expApp .filter-actions {
  display: flex;
  gap: 10px;
}

#expApp .filterbtn,
#expApp .resetbtn {
  min-width: 100px;
  min-height: 40px;
  padding: 9px 18px;
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 800;
  cursor: pointer;
  transition: transform .12s ease;
}

#expApp .filterbtn {
  border: 1px solid var(--life-green-800);
  background: linear-gradient(135deg, var(--life-green-700), var(--life-green-600));
  color: #fff;
  box-shadow: 0 5px 12px rgba(27,94,32,.18);
}

#expApp .resetbtn {
  border: 1.5px solid var(--life-green-600);
  background: #fff;
  color: var(--life-green-800);
}

#expApp .filterbtn:hover,
#expApp .resetbtn:hover { transform: translateY(-1px); }

/* ───────────────────────────── Summary Cards (ACC .kpi) ────────────── */
#expApp .scards {
  display: grid;
  gap: 13px;
}

#expApp .scards-primary   { grid-template-columns: repeat(3, minmax(0, 1fr)); }
#expApp .scards-secondary { margin-top: 13px; grid-template-columns: repeat(2, minmax(0, 1fr)); }

#expApp .scards-all {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(5, minmax(230px, 1fr));
  gap: 13px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 2px 8px;
  scrollbar-width: thin;
}

#expApp .scard,
#expApp .scards-all .scard {
  min-width: 230px;
  min-height: 104px;
  padding: 18px 20px;
  border: 1px solid #CDE8D1;
  border-radius: 16px;
  background: var(--life-green-100);
  box-shadow: 0 4px 12px rgba(15,61,30,.07);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 5px;
  transition: .15s ease;
}

#expApp .scard:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(15,61,30,.11);
}

#expApp .scard-topline {
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

#expApp .scard-icon { font-size: 20px; line-height: 1; }

#expApp .scard-chip {
  padding: 3px 9px;
  border-radius: 99px;
  background: rgba(255,255,255,.75);
  color: var(--life-muted);
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .3px;
}

#expApp .scard-amt {
  color: var(--life-green-800);
  font-family: var(--disp);
  font-size: 34px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -.5px;
  word-break: break-word;
}

#expApp .scard-label {
  margin-top: 4px;
  color: var(--life-green-900);
  font-size: 14px;
  font-weight: 700;
}

#expApp .scard-sub {
  color: var(--life-muted);
  font-size: 11.5px;
  font-weight: 600;
}

#expApp .scard-count {
  color: var(--life-muted);
  font-size: 11.5px;
  font-weight: 600;
}

#expApp .scard-detail {
  margin-top: 4px;
  color: var(--life-muted);
  font-size: 11.5px;
  line-height: 1.5;
}

#expApp .scard-exp .scard-amt     { color: var(--life-red); }
#expApp .scard-bal .scard-amt     { color: var(--life-green-800); }
#expApp .scard-opening .scard-amt { color: var(--life-amber); }
#expApp .scard-ho .scard-amt      { color: var(--life-blue); }

/* ───────────────────────────── Entry Header ────────────────────────── */
#expApp .expenditure-form { margin-top: 13px; }

#expApp .life-entry-title {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--life-border);
}

#expApp .entry-status-wrap {
  display: flex;
  align-items: center;
  gap: 9px;
}

#expApp .eno {
  padding: 6px 12px;
  border: 1px solid var(--life-border);
  border-radius: 8px;
  background: var(--life-green-50);
  color: var(--life-green-800);
  font-family: var(--disp);
  font-size: 11.5px;
  font-weight: 800;
}

#expApp .esp {
  padding: 6px 12px;
  border-radius: 99px;
  font-size: 11px;
  font-weight: 800;
}

#expApp .esp.draft {
  border: 1px solid #F1D58C;
  background: var(--life-amberbg, #FFF3E0);
  color: #8B6500;
}

#expApp .esp.posted {
  border: 1px solid #A9DCAF;
  background: var(--life-green-100);
  color: var(--life-green-700);
}

#expApp .eh {
  margin-bottom: 13px;
  padding: 15px 17px;
  border: 1px solid var(--life-border);
  border-radius: 14px;
  background: var(--life-green-50);
}

#expApp .entry-head-fields {
  display: grid;
  grid-template-columns: minmax(250px, 1.2fr) minmax(170px, .55fr) minmax(180px, .7fr);
  gap: 15px;
  align-items: end;
}

#expApp .entry-field { min-width: 0; }

#expApp .elbl,
#expApp .flbl {
  margin-bottom: 6px;
  display: block;
  color: var(--life-muted);
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .9px;
  text-transform: uppercase;
}

#expApp .req { color: var(--life-red); }

#expApp .hsel,
#expApp .hdate,
#expApp .pgrid select {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1.5px solid var(--life-border);
  border-radius: 9px;
  outline: none;
  background: #fff;
  color: var(--life-text);
  font-size: 12.5px;
}

#expApp .hsel:focus,
#expApp .hdate:focus,
#expApp .pgrid select:focus {
  border-color: var(--life-green-500);
  box-shadow: 0 0 0 3px rgba(67,160,71,.12);
}

#expApp .entry-series #eSeriesDisp {
  min-height: 40px;
  padding: 10px 12px;
  border: 1px dashed #AAD4B0;
  border-radius: 9px;
  background: var(--life-green-50);
  display: block;
  color: var(--life-green-700);
  font-family: var(--disp);
  font-size: 11.5px;
  font-weight: 800;
}

/* ───────────────────────────── Section Boxes (ACC .sect) ───────────── */
#expApp .ec {
  margin-top: 13px;
  border: 1px solid var(--life-border);
  border-radius: 14px;
  background: #fff;
  overflow: hidden;
}

#expApp .ech {
  min-height: 46px;
  padding: 12px 15px;
  background: linear-gradient(135deg, var(--life-green-700), var(--life-green-600));
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

#expApp .echt {
  color: #fff;
  font-family: var(--disp);
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: .25px;
  text-transform: none;
}

#expApp .ech-sub {
  margin-left: 8px;
  color: rgba(255,255,255,.8);
  font-size: 10px;
  font-style: normal;
}

#expApp .branch-hint {
  color: rgba(255,255,255,.9);
  font-size: 10px;
  font-weight: 700;
  font-style: normal;
}

#expApp .addbtn,
#expApp .exportbtn {
  min-height: 32px;
  padding: 6px 12px;
  border: 0;
  border-radius: 8px;
  background: #fff;
  color: var(--life-green-800);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 3px 8px rgba(0,0,0,.12);
}

#expApp .addbtn:hover,
#expApp .exportbtn:hover {
  filter: brightness(.98);
  transform: translateY(-1px);
}

/* ───────────────────────────── Tables (ACC .tbl) ───────────────────── */
#expApp .table-scroll { width: 100%; overflow: auto; }
#expApp .table-scroll-items { max-height: 520px; }
#expApp .history-scroll { min-height: 410px; max-height: 540px; }

#expApp table {
  width: 100%;
  min-width: 1180px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 12.3px;
}

#expApp thead th {
  padding: 8px 9px;
  position: sticky;
  top: 0;
  z-index: 4;
  border-bottom: 1px solid #CDE8D1;
  background: var(--life-green-100);
  color: var(--life-green-800);
  font-size: 9.8px;
  font-weight: 800;
  letter-spacing: .8px;
  text-transform: uppercase;
  white-space: nowrap;
  text-align: left;
}

#expApp thead th.r { text-align: right; }
#expApp thead th.c { text-align: center; }

#expApp tbody td {
  padding: 8px 9px;
  border-right: .5px solid rgba(46,125,50,.16);
  border-bottom: .5px solid rgba(46,125,50,.16);
  color: var(--life-text);
  vertical-align: middle;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 210px;
}

#expApp #eTbody tr:nth-child(odd) td,
#expApp #eHistoryBody tr:nth-child(odd) td { background: #fff; }

#expApp #eTbody tr:nth-child(even) td,
#expApp #eHistoryBody tr:nth-child(even) td { background: var(--life-green-50); }

#expApp #eTbody tr:hover td,
#expApp #eHistoryBody tr:hover td { background: var(--life-green-100); }

#expApp td.rn {
  width: 38px;
  max-width: 38px;
  color: var(--life-muted);
  text-align: center;
  font-weight: 800;
}

#expApp td.r {
  text-align: right;
  font-family: var(--disp);
  font-weight: 700;
}

#expApp td.c { text-align: center; }

#expApp td.nodata {
  padding: 34px;
  color: var(--life-muted);
  text-align: center;
  font-style: italic;
  white-space: normal;
  max-width: none;
}

#expApp .ec select,
#expApp .ec input[type="text"],
#expApp .ec input[type="number"] {
  width: 100%;
  min-height: 36px;
  padding: 7px 9px;
  border: 1.5px solid var(--life-border);
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: var(--life-text);
  font-size: 12.5px;
}

#expApp .ec select:focus,
#expApp .ec input[type="text"]:focus,
#expApp .ec input[type="number"]:focus {
  border-color: var(--life-green-500);
  box-shadow: 0 0 0 3px rgba(67,160,71,.12);
}

#expApp .ec input[type="number"] { text-align: right; }

#expApp .ec input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--life-green-600);
  cursor: pointer;
}

#expApp .ec input[type="file"] {
  width: 100%;
  padding: 5px;
  border: 1px dashed #BDD9C2;
  border-radius: 7px;
  background: var(--life-green-50);
  color: var(--life-muted);
  font-size: 12px;
}

#expApp .ec input[type="file"]:disabled { opacity: .45; cursor: not-allowed; }

#expApp .ec input[type="file"].req-file {
  border-color: var(--life-red);
  background: var(--life-redbg);
}

#expApp .lt {
  max-width: 180px;
  padding: 3px 9px;
  border: 1px solid #AEE0B6;
  border-radius: 99px;
  background: var(--life-green-100);
  color: var(--life-green-700);
  display: inline-block;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 9.6px;
  font-weight: 800;
  letter-spacing: .3px;
  white-space: nowrap;
}

#expApp .le {
  color: #A9B8AC;
  font-size: 11px;
  font-style: italic;
}

#expApp .delbtn {
  padding: 4px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #EF9B9E;
  cursor: pointer;
}

#expApp .delbtn:hover {
  background: var(--life-redbg);
  color: var(--life-red);
}

#expApp .totbar {
  min-height: 52px;
  padding: 12px 18px;
  background: linear-gradient(135deg, var(--life-green-900), var(--life-green-700));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

#expApp .totlbl {
  color: #BFE3C4;
  font-size: 9.8px;
  font-weight: 800;
  letter-spacing: .8px;
  text-transform: uppercase;
}

#expApp .totamt {
  color: #fff;
  font-family: var(--disp);
  font-size: 21px;
  font-weight: 800;
}

/* ───────────────────────────── Payment Details ─────────────────────── */
#expApp .pgrid {
  padding: 15px 17px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
