// ── Date validation: restrict to today's date only ────────────────────────
function restrictDateToToday() {
  var dateInput = q('#eEntryDate');
  if(dateInput) {
    var today = todayISO();
    dateInput.setAttribute('max', today);
    dateInput.setAttribute('min', today);
    dateInput.value = today;

    // Prevent manual date changes
    dateInput.addEventListener('change', function() {
      var selectedDate = this.value;
      if(selectedDate !== today) {
        frappe.show_alert({message: '📅 Only today\'s date (' + fmtDisp(today) + ') is allowed!', indicator: 'orange'}, 4);
        this.value = today;
      }
    });

    // Also prevent via keypress
    dateInput.addEventListener('keydown', function(e) {
      if(e.key !== 'Tab' && e.key !== 'Escape') {
        e.preventDefault();
        frappe.show_alert({message: '📅 Use the date picker to select today only', indicator: 'orange'}, 3);
      }
    });
  }
}

// ── Period helpers (6th to 5th cycle) ─────────────────────────────────────
function periodFrom() {
  var d = new Date(), y = d.getFullYear(), m = d.getMonth();
  if(d.getDate() >= 6) return y+'-'+String(m+1).padStart(2,'0')+'-06';
  var pm = m===0?12:m, py = m===0?y-1:y;
  return py+'-'+String(pm).padStart(2,'0')+'-06';
}
function periodTo() {
  var d = new Date(), y = d.getFullYear(), m = d.getMonth();
  if(d.getDate() >= 6) { var nm = m+2, ny = y; if(nm>12){nm=1;ny=y+1;} return ny+'-'+String(nm).padStart(2,'0')+'-05'; }
  return y+'-'+String(m+1).padStart(2,'0')+'-05';
}

// ── Previous period (for closing balance carry-forward) ──────────────────
function prevPeriodFrom() {
  var curFrom = periodFrom();
  var p = curFrom.split('-'), y = parseInt(p[0]), m = parseInt(p[1]);
  var pm = m===1?12:m-1, py = m===1?y-1:y;
  return py+'-'+String(pm).padStart(2,'0')+'-06';
}
function prevPeriodTo() {
  // Previous period end = day before current period start
  var curFrom = periodFrom();
  var d = new Date(curFrom);
  d.setDate(d.getDate()-1);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

function normalizeMode(mode) {
  var m = (mode||'').toLowerCase();
  if(m.includes('cash'))   return 'CASH';
