    freeze: false,
    callback: function(r) {
      var list = [];

      if(Array.isArray(r.message)) {
        list = r.message;
      } else if(r.message && Array.isArray(r.message.employees)) {
        list = r.message.employees;
      }

      var employeeMap = {};
      list.forEach(function(emp) {
        if(emp && emp.name) employeeMap[emp.name] = emp;
