// ── Per-row bill upload & attach ──────────────────────────────────────────
// Each expenditure row keeps its own bill URL in the matching
// Journal Entry Account.user_remark as [[BILLURL:<encoded-url>]].
// This prevents one parent-level bill from appearing against every row.
function apiUploadRowBill(jeName, file, rowNo, cb) {
  if(!file) { cb(null, null); return; }

  var safeName = String(file.name || 'bill')
    .replace(/[^A-Za-z0-9._-]+/g, '_');
  var uploadName = 'EXP_ROW_' + String(rowNo).padStart(2, '0') + '_' + Date.now() + '_' + safeName;

  var formData = new FormData();
  formData.append('file', file, uploadName);
  formData.append('doctype', 'Journal Entry');
  formData.append('docname', jeName);
  formData.append('is_private', '0');

  fetch('/api/method/upload_file', {
    method: 'POST',
    headers: {'X-Frappe-CSRF-Token': frappe.csrf_token},
    body: formData
  })
  .then(function(res) {
    return res.json().then(function(data) {
      if(!res.ok) {
        throw new Error((data && (data.exception || data.message)) || ('Upload failed (' + res.status + ')'));
      }
      return data;
    });
  })
  .then(function(data) {
    var url = data.message && (data.message.file_url || data.message.name);
    if(url) cb(url, null);
    else cb(null, new Error('No file URL returned for row ' + rowNo));
  })
  .catch(function(err) {
    cb(null, err || new Error('Bill upload failed for row ' + rowNo));
  });
}

function stripRowBillMarker(text) {
  return String(text || '')
    .replace(/\s*\|?\s*\[\[BILLURL:[^\]]+\]\]\s*/g, '')
    .trim();
}

function getRowBillUrl(text) {
  var m = String(text || '').match(/\[\[BILLURL:([^\]]+)\]\]/);
  if(!m || !m[1]) return '';
  try { return decodeURIComponent(m[1]); }
  catch(e) { return m[1]; }
}

