function apiUploadBillsPerRow(jeName, items, cb) {
  apiJEDoc(jeName, function(doc) {
    var debitRows = (doc.accounts || [])
      .filter(function(acc) {
        return (parseFloat(acc.debit_in_account_currency || 0) || 0) > 0;
      })
      .sort(function(a, b) {
        return (parseInt(a.idx || 0, 10) || 0) - (parseInt(b.idx || 0, 10) || 0);
      });

    if(debitRows.length < items.length) {
      cb(false, new Error('Could not match expenditure rows to Journal Entry rows.'));
      return;
    }

    var i = 0;
    var firstBillUrl = '';

    function next() {
      if(i >= items.length) {
        // Keep the first bill in the old parent field only for backward
        // compatibility with the standard Journal Entry view. History below
        // uses the per-row marker and does NOT copy it to other rows.
        apiSetLegacyParentBill(jeName, firstBillUrl, function() {
          cb(true, null);
        });
        return;
      }

      var itemIndex = i;
      var item = items[itemIndex];
      var child = debitRows[itemIndex];
      i++;

      if(!item.bv || !item.billFile) {
        next();
        return;
      }

      apiUploadRowBill(jeName, item.billFile, itemIndex + 1, function(url, uploadErr) {
        if(uploadErr || !url) {
          cb(false, uploadErr || new Error('Bill upload failed for row ' + (itemIndex + 1)));
          return;
        }

        if(!firstBillUrl) firstBillUrl = url;

        var baseRemark = stripRowBillMarker(child.user_remark || '');
        var marker = '[[BILLURL:' + encodeURIComponent(url) + ']]';
        var newRemark = baseRemark ? (baseRemark + ' | ' + marker) : marker;

        apiSetJEAccountRemark(child.name, newRemark, function(ok, saveErr) {
          if(!ok) {
            cb(false, saveErr || new Error('Could not save bill mapping for row ' + (itemIndex + 1)));
            return;
          }
          next();
        });
      });
    }

    next();
  });
}

