// ── Compute closing balance for a set of entries + payments ───────────────
// Returns: { cashIn, cashOut, cashToHO, manualIn, balance }
function computeBalance(entries, payments) {
  var cashIn = 0, manualIn = 0, cashOut = 0, cashToHO = 0;
  payments.forEach(function(p) {
    if(normalizeMode(p.mode_of_payment) === 'CASH') cashIn += (p.paid_amount||0);
  });
  entries.forEach(function(entry) {
    entry.items.forEach(function(item) {
      if(CASH_IN_TYPES.indexOf(item.et) > -1) {
        manualIn += item.av;
      } else if(CASH_TO_HO_TYPES.indexOf(item.et) > -1) {
        cashToHO += item.av;
      } else {
        cashOut += item.av;
      }
    });
  });
  var balance = cashIn + manualIn - cashOut - cashToHO;
  return { cashIn:cashIn, manualIn:manualIn, cashOut:cashOut, cashToHO:cashToHO, balance:balance };
}

// ── Load previous period entries to get closing balance ───────────────────
function loadPrevPeriodBalance(filterBranch, cb) {
  var pFrom = prevPeriodFrom(), pTo = prevPeriodTo();
  var queryBranch = currentUserBranch || filterBranch;
  apiJEList(pFrom, pTo, queryBranch, function(jes) {
    if(!jes.length) { apiPayments(pFrom, pTo, queryBranch, function(pmts) { cb(computeBalance([], pmts)); }); return; }
    var fetched = 0, total = jes.length, prevEntries = [];
    jes.forEach(function(je) {
      apiJEDoc(je.name, function(doc) {
        var rm = je.user_remark||'', branch='', payMode='', paidBy='', approvedBy='';
        var bm = rm.match(/Branch:([^|]+)/);         if(bm) branch      = bm[1].trim();
        var mm = rm.match(/\|\s*([^|]+)\s*\|\s*By:/); if(mm) payMode    = mm[1].trim();
        var pm = rm.match(/By:([^|]+)/);               if(pm) paidBy     = pm[1].trim();
        var am = rm.match(/Approved:([^|]+)/);         if(am) approvedBy = am[1].trim();
        var items = [], t = 0;
        (doc.accounts||[]).forEach(function(acc) {
          if((acc.debit_in_account_currency||0) > 0) {
            var remark = acc.user_remark||'', parts = remark.split(' | '),
                main = parts[0]||'', rv = parts[1]||'';
            var dash = main.indexOf(' - '),
                et = dash>-1 ? main.substring(0,dash) : main,
                dv = dash>-1 ? main.substring(dash+3) : '';
            var av = acc.debit_in_account_currency||0; t += av;
            items.push({et:et, dv:dv, lv:acc.account, av:av, rv:rv});
          }
        });
        if(items.length) prevEntries.push({date:je.posting_date, branch:branch, je:je.name, paidBy:paidBy, approvedBy:approvedBy, payMode:payMode, total:t, items:items});
        fetched++;
        if(fetched === total) {
          var eff = currentUserBranch || filterBranch;
          var filtered = eff ? prevEntries.filter(function(e){ return e.branch === eff; }) : prevEntries;
          apiPayments(pFrom, pTo, eff, function(pmts) {
            cb(computeBalance(filtered, pmts));
          });
        }
      });
    });
  });
}

// ── Summary cards ─────────────────────────────────────────────────────────
function updateCards(entries, fromDate, toDate, filterBranch) {
  var payments_fetched = false, prev_fetched = false;
  var curResult = {}, prevResult = {};

  function renderAll() {
    if(!payments_fetched || !prev_fetched) return;

    var prevBalance = prevResult.balance || 0;

    var cashIn    = curResult.cashIn    || 0;
    var manualIn  = curResult.manualIn  || 0;
    var cashOut   = curResult.cashOut   || 0;
    var cashToHO  = curResult.cashToHO  || 0;
    var cashCount = curResult.cashCount || 0;

    var totalIn = cashIn + manualIn + prevBalance;
    var totalOut = cashOut + cashToHO;
    var balance = totalIn - totalOut;

    q('#sCashIn').textContent = fmtAmt(cashIn + manualIn);
    q('#sCashInCount').textContent = cashCount + ' payment entr' + (cashCount===1?'y':'ies') +
      (manualIn > 0 ? ' + receipts' : '');
    q('#sCashInDetail').innerHTML =
      'Payment Entry (Cash): <b>'+fmtAmt(cashIn)+'</b>' +
      (manualIn > 0 ? '<br>Manual Receipts: <b>'+fmtAmt(manualIn)+'</b>' : '');

    q('#sCashOut').textContent = fmtAmt(cashOut);
    q('#sCashOutCount').textContent = entries.length + ' entr' + (entries.length===1?'y':'ies') +
      (cashToHO > 0 ? ' | HO: '+fmtAmt(cashToHO) : '');
    var mh = ''; var expByMode = curResult.expByMode || {};
    Object.keys(expByMode).sort().forEach(function(m) { mh += m+': '+fmtAmt(expByMode[m])+'<br>'; });
    if(cashToHO > 0) mh += '<span style="color:#f87171">&#x2192; HO Transfer: <b>'+fmtAmt(cashToHO)+'</b></span>';
    q('#sCashOutDetail').innerHTML = mh || '';

    q('#sBalance').textContent = fmtAmt(Math.abs(balance));
    q('#sBalance').style.color = balance >= 0 ? '#E65100' : '#C62828';
    q('#sBalanceLabel').textContent = balance >= 0 ? '💚 Cash Surplus' : '🔴 Cash Deficit';
    q('#sBalanceLabel').style.color = balance >= 0 ? '#E65100' : '#C62828';
    q('#sBalanceDetail').innerHTML =
      (prevBalance > 0 ? 'Opening: <b>'+fmtAmt(prevBalance)+'</b><br>' : '') +
      fmtAmt(cashIn+manualIn)+' collected<br>' +
      (cashToHO > 0 ? '&#x2212; '+fmtAmt(cashToHO)+' to HO<br>' : '') +
      '&#x2212; '+fmtAmt(cashOut)+' spent<br>' +
      '<b style="color:'+(balance>=0?'#E65100':'#C62828')+'">' +
      (balance>=0?'▲ Closing Balance':'▼ Deficit')+' '+fmtAmt(Math.abs(balance))+'</b>';

    var prevBal = prevResult.balance || 0;
    var prevCashIn = prevResult.cashIn || 0;
    var prevManual = prevResult.manualIn || 0;
    var prevOut = prevResult.cashOut || 0;
    var prevToHO = prevResult.cashToHO || 0;
    var card4El = q('#sOpeningCard');
    if(card4El) {
      q('#sOpening').textContent = fmtAmt(Math.abs(prevBal));
      q('#sOpening').style.color = prevBal >= 0 ? '#1E3A5F' : '#C62828';
      q('#sOpeningLabel').textContent = prevBal >= 0 ? '📅 Last Month Closing' : '🔴 Last Month Deficit';
      q('#sOpeningDetail').innerHTML =
        'Collected: <b>'+fmtAmt(prevCashIn+prevManual)+'</b><br>' +
        'Spent: <b>'+fmtAmt(prevOut)+'</b>' +
        (prevToHO > 0 ? '<br>To HO: <b>'+fmtAmt(prevToHO)+'</b>' : '') +
        '<br><b style="color:'+(prevBal>=0?'#1E3A5F':'#C62828')+'">Closing: '+fmtAmt(Math.abs(prevBal))+'</b>';
    }

    var card5El = q('#sHOCard');
    if(card5El) {
      q('#sHOCash').textContent = fmtAmt(cashToHO);
      q('#sHODetail').innerHTML = cashToHO > 0
        ? 'Transferred to Head Office<br><span style="font-size:12px;opacity:.78">Posted to Cash-Hitech - LSACPL</span>'
        : 'No HO transfers this period';
    }
  }

  var expCashIn = 0, expCashOut = 0, expCashToHO = 0, expByMode = {};
  entries.forEach(function(entry) {
    var entryExpTotal = 0;
    entry.items.forEach(function(item) {
      if(CASH_IN_TYPES.indexOf(item.et) > -1) {
        expCashIn += item.av;
      } else if(CASH_TO_HO_TYPES.indexOf(item.et) > -1) {
        expCashToHO += item.av;
      } else {
        expCashOut += item.av;
        entryExpTotal += item.av;
      }
    });
    if(entryExpTotal > 0) expByMode[entry.payMode] = (expByMode[entry.payMode]||0) + entryExpTotal;
  });

  apiPayments(fromDate, toDate, filterBranch, function(payments) {
    var cashIn = 0, cashCount = 0;
    payments.forEach(function(p) {
      if(normalizeMode(p.mode_of_payment)==='CASH') { cashIn += (p.paid_amount||0); cashCount++; }
    });
    curResult = {
      cashIn: cashIn, manualIn: expCashIn, cashOut: expCashOut,
      cashToHO: expCashToHO, cashCount: cashCount,
      balance: cashIn + expCashIn - expCashOut - expCashToHO,
      expByMode: expByMode
    };
    payments_fetched = true;
    renderAll();
  });

  loadPrevPeriodBalance(filterBranch, function(res) {
    prevResult = res;
    prev_fetched = true;
    renderAll();
  });
}

// ── Render history ────────────────────────────────────────────────────────
function renderHistory(entries, fromDate, toDate, filterBranch) {
  entries = (entries || []).filter(function(entry) {
    return entry && !isExcludedBranch(entry.branch);
  });
  fromDate     = fromDate     || q('#eFilterFrom').value   || periodFrom();
  toDate       = toDate       || q('#eFilterTo').value     || periodTo();
  filterBranch = filterBranch || q('#eFilterBranch').value || '';
  var effectiveBranch = currentUserBranch || filterBranch;
  var visibleEntries = effectiveBranch
    ? entries.filter(function(e) { return e.branch === effectiveBranch; })
    : entries;
  lastVisibleEntries = visibleEntries;
  lastVisibleFrom = fromDate;
  lastVisibleTo = toDate;
  lastVisibleBranch = effectiveBranch;
  updateCards(visibleEntries, fromDate, toDate, effectiveBranch);
  var tb = q('#eHistoryBody');
  if(!visibleEntries||!visibleEntries.length) {
    tb.innerHTML = '<tr><td colspan="13" class="nodata">No submitted entries yet.</td></tr>';
    q('#eGrandTotal').textContent = fmtAmt(0); return;
  }
  var grand = 0, rowNum = 0, html = '';
  visibleEntries.forEach(function(entry) {
    entry.items.forEach(function(item, idx) {
      rowNum++; grand += item.av;
      var th = '&#x2014;';
      if(item.bv && item.previewSrc) {
        th = item.isPdf
          ? '<a href="'+item.previewSrc+'" target="_blank" class="pdf-prev-sm">📄 PDF</a>'
          : '<img src="'+item.previewSrc+'" class="hist-thumb" data-src="'+item.previewSrc+'" data-name="'+item.fileName+'" title="Click" style="cursor:pointer"/>';
      } else if(item.bv) { th = '<span class="bill-yes">&#x2713;</span>'; }

      var isCashInRow = CASH_IN_TYPES.indexOf(item.et) > -1;
      var isHORow     = CASH_TO_HO_TYPES.indexOf(item.et) > -1;
      var rowBg = isCashInRow ? 'background:#f0fdf4' : (isHORow ? 'background:#fff7ed' : '');
      var amtColor = isCashInRow ? 'color:#16a34a;font-weight:700' : (isHORow ? 'color:#ea580c;font-weight:700' : '');
      var prefix = isCashInRow
        ? '<span style="color:#16a34a;font-weight:700">&#x2191; </span>'
        : (isHORow ? '<span style="color:#ea580c;font-weight:700">&#x2192;HO </span>' : '');

      html += '<tr style="'+rowBg+'">'+
        '<td class="rn">'+rowNum+'</td>'+
        '<td>'+fmtDisp(entry.date)+'</td>'+
        '<td><b>'+entry.branch+'</b></td>'+
        '<td title="'+item.et+'">'+prefix+item.et+'</td>'+
        '<td><span class="lt" title="'+item.lv+'">'+item.lv+'</span></td>'+
        '<td title="'+(item.dv||'')+'">'+(item.dv||'&#x2014;')+'</td>'+
        '<td class="r" style="'+amtColor+'">'+fmtAmt(item.av)+'</td>'+
        '<td>'+(idx===0?entry.paidBy:'')+'</td>'+
        '<td>'+(idx===0?entry.approvedBy:'')+'</td>'+
        '<td>'+(idx===0?'<span class="mode-pill">'+entry.payMode+'</span>':'')+'</td>'+
        '<td class="c"><span class="'+(item.bv?'bill-yes':'bill-no')+'">'+(item.bv?'&#x2713;':'NO')+'</span></td>'+
        '<td class="c">'+th+'</td>'+
        '<td title="'+(item.rv||'')+'">'+(item.rv||'&#x2014;')+'</td></tr>';
    });
  });
  tb.innerHTML = html;
  q('#eGrandTotal').textContent = fmtAmt(grand);
  qa('#eHistoryBody .hist-thumb').forEach(function(img) {
    img.addEventListener('click', function() {
      openLightbox(this.getAttribute('data-src'), this.getAttribute('data-name'));
    });
  });
}

// ── Export Excel ──────────────────────────────────────────────────────────
function exportExcel() {
  if(!lastVisibleEntries || !lastVisibleEntries.length) {
    frappe.msgprint('No data to export.');
    return;
  }
  var fromD = lastVisibleFrom, toD = lastVisibleTo;
  var branchTag = lastVisibleBranch || 'AllBranches';
  var filename = 'ExpenditureEntries_' + branchTag.replace(/\s+/g,'') + '_' + fromD + '_to_' + toD + '.csv';

  var csvRows = [];
  csvRows.push(['Expenditure Entries Report']);
  csvRows.push(['Branch: ' + (lastVisibleBranch || 'All Branches')]);
  csvRows.push(['Date Range: ' + fmtDisp(fromD) + ' to ' + fmtDisp(toD)]);
  csvRows.push([]);
  csvRows.push(['#','Date','Branch','Expenditure Type','Ledger Category','Description','Amount','Paid By','Approved By','Mode','Bill','Remarks']);

  var grand = 0, rowNum = 0;
  lastVisibleEntries.forEach(function(entry) {
    entry.items.forEach(function(item, idx) {
      rowNum++; grand += item.av;
      csvRows.push([
        rowNum, fmtDisp(entry.date), entry.branch, item.et, item.lv, item.dv || '',
        item.av, idx===0 ? entry.paidBy : '', idx===0 ? entry.approvedBy : '',
        idx===0 ? entry.payMode : '', item.bv ? 'Yes' : 'No', item.rv || ''
      ]);
    });
  });
  csvRows.push([]);
  csvRows.push(['','','','','','Grand Total', grand,'','','','','']);

  var csv = csvRows.map(function(row) {
    return row.map(function(cell) {
      var s = String(cell==null ? '' : cell);
      if(s.indexOf(',')>=0 || s.indexOf('"')>=0 || s.indexOf('\n')>=0) s = '"' + s.replace(/"/g,'""') + '"';
      return s;
    }).join(',');
  }).join('\n');

  var blob = new Blob(['\uFEFF'+csv], {type:'text/csv;charset=utf-8;'});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  frappe.show_alert({message:'Exported: ' + filename, indicator:'green'}, 4);
}

// ── Load JE history ───────────────────────────────────────────────────────
function loadJEHistory(fromDate, toDate, filterBranch, callback) {
  q('#eHistoryBody').innerHTML = '<tr><td colspan="13" class="nodata" style="color:#64748b">&#x23F3; Loading entries...</td></tr>';
  var queryBranch = currentUserBranch || filterBranch;
  apiJEList(fromDate, toDate, queryBranch, function(jes) {
    allEntries = [];
    if(!jes.length) { renderHistory([], fromDate, toDate, queryBranch); if(callback) callback(); return; }
    var fetched = 0, total = jes.length, lineMap = {};
    jes.forEach(function(je) {
      apiJEDoc(je.name, function(doc) {
        var billUrl = doc.custom_bill_recipt || '';
        var isPdf = billUrl.toLowerCase().endsWith('.pdf');
        if(!lineMap[je.name]) lineMap[je.name] = {rows:[], billUrl:billUrl, isPdf:isPdf};
        (doc.accounts||[]).forEach(function(acc) {
          if((acc.debit_in_account_currency||0) > 0) {
            lineMap[je.name].rows.push({
              parent: je.name, account: acc.account,
              debit_in_account_currency: acc.debit_in_account_currency,
              user_remark: acc.user_remark||''
            });
          }
        });
        fetched++;
        if(fetched === total) {
          jes.forEach(function(je) {
            var rm = je.user_remark||'', branch='', payMode='', paidBy='', approvedBy='';
            var bm = rm.match(/Branch:([^|]+)/);         if(bm) branch      = bm[1].trim();
            var mm = rm.match(/\|\s*([^|]+)\s*\|\s*By:/); if(mm) payMode    = mm[1].trim();
            var pm = rm.match(/By:([^|]+)/);               if(pm) paidBy     = pm[1].trim();
            var am = rm.match(/Approved:([^|]+)/);         if(am) approvedBy = am[1].trim();
            var items = [], t = 0;
            var jeData = lineMap[je.name] || {rows:[], billUrl:'', isPdf:false};
            var legacyBillUrl = jeData.billUrl || '';
            var rowsForEntry = jeData.rows || [];
            var hasPerRowBillMarkers = rowsForEntry.some(function(acc) {
              return !!getRowBillUrl(acc.user_remark || '');
            });

            rowsForEntry.forEach(function(acc) {
              var rawRemark = acc.user_remark || '';
              var rowBillUrl = getRowBillUrl(rawRemark);
              var cleanRemark = stripRowBillMarker(rawRemark);
              var parts = cleanRemark.split(' | '),
                  main = parts[0] || '', rv = parts[1] || '';

              var dash = main.indexOf(' - '),
                  et = dash>-1 ? main.substring(0,dash) : main,
                  dv = dash>-1 ? main.substring(dash+3) : '';

              var av = acc.debit_in_account_currency || 0;
              t += av;

              // New records: use only the bill mapped to this exact row.
              // Old records: if no row markers exist at all, fall back to the
              // old parent-level custom_bill_recipt behavior.
              var effectiveBillUrl = rowBillUrl || (!hasPerRowBillMarkers ? legacyBillUrl : '');
              var effectiveIsPdf = !!effectiveBillUrl &&
                effectiveBillUrl.split('?')[0].toLowerCase().endsWith('.pdf');

              items.push({
                et:et, dv:dv, lv:acc.account, av:av, rv:rv,
                bv:!!effectiveBillUrl,
                previewSrc:effectiveBillUrl,
                fileName:effectiveBillUrl ? effectiveBillUrl.split('/').pop().split('?')[0] : '',
                isPdf:effectiveIsPdf
              });
            });
            if(items.length) allEntries.push({
              date:je.posting_date, branch:branch, je:je.name,
              paidBy:paidBy, approvedBy:approvedBy, payMode:payMode,
              total:t, items:items,
              billUrl:legacyBillUrl,
              billIsPdf:!!jeData.isPdf
            });
          });
          allEntries.sort(function(a,b) { return b.date.localeCompare(a.date); });
          renderHistory(allEntries, fromDate, toDate, queryBranch);
          if(callback) callback();
        }
      });
    });
  });
}

// ═══ INIT ═══════════════════════════════════════════════════════════════
$(document).ready(function() {
  buildLightbox();
  updateLifeHeaderClock();
  window.setInterval(updateLifeHeaderClock, 1000);

  // Initialize date restrictions
  restrictDateToToday();

  addRow(); addRow(); addRow();
