      currentUserBranch = '';
      branch = '';
    }
    setLoginBranchBadge(branch);
    loadBranches();
  });

  q('#eBranch').addEventListener('change', function() {
    loadEmployees(this.value);
  });

  setupStaffComboInput(q('#ePaidBy'), function() {
    return paidByAllowedValues;
  }, 'Paid By staff name');

  setupStaffComboInput(q('#eApprovedBy'), function() {
    return approvedByAllowedValues;
  }, 'Approved By staff name');

  q('#eAddBtn').addEventListener('click', addRow);
  var expBtn = q('#eExportBtn');
  if(expBtn) expBtn.addEventListener('click', exportExcel);
  q('#eDraftBtn').addEventListener('click', function() {
    frappe.show_alert({message:'Fill all fields then click Submit.', indicator:'blue'}, 3);
  });
  q('#eFilterBtn').addEventListener('click', function() {
    var fb = currentUserBranch || q('#eFilterBranch').value;
    loadJEHistory(q('#eFilterFrom').value, q('#eFilterTo').value, fb, null);
  });
  q('#eResetBtn').addEventListener('click', function() {
    var fb = currentUserBranch || '';
    q('#eFilterBranch').value = currentUserBranch || '';
    q('#eFilterFrom').value = periodFrom();
    q('#eFilterTo').value   = periodTo();
    loadJEHistory(periodFrom(), periodTo(), fb, null);
  });
  rootElement.addEventListener('click', function(e) {
    if(e.target && e.target.id === 'eNewEntryBtn') resetForm();
  });
  rootElement.addEventListener('change', function(e) {
    if(e.target) e.target.classList.remove('ferr');
  });

  // ── SUBMIT ────────────────────────────────────────────────────────────
  q('#eSubmitBtn').addEventListener('click', function() {
    if(saved) return;
    if(this.dataset.submitting === '1') return;
    this.dataset.submitting = '1';

    var branch = q('#eBranch').value, edate = q('#eEntryDate').value;
    if(!branch) {
      q('#eBranch').classList.add('ferr');
      frappe.msgprint({title:'Branch Required', message:'Please select a Branch.', indicator:'red'});
      this.dataset.submitting = '0'; return;
    }
    if(!edate) {
      q('#eEntryDate').classList.add('ferr');
      frappe.msgprint({title:'Date Required', message:'Please select a date.', indicator:'red'});
      this.dataset.submitting = '0'; return;
    }

    // Validate date is today
    var today = todayISO();
    if(edate !== today) {
      q('#eEntryDate').classList.add('ferr');
      frappe.msgprint({title:'Invalid Date', message:'Only today\'s date (' + fmtDisp(today) + ') is allowed.', indicator:'red'});
      this.dataset.submitting = '0';
      q('#eEntryDate').value = today;
      return;
    }

    var items = [], valid = true;
    qa('#eTbody tr').forEach(function(tr) {
      var sel  = tr.querySelector('.etsel'), desc = tr.querySelector('.edesc'),
          amt  = tr.querySelector('.eamt'),  rm   = tr.querySelector('.erm'),
          bill = tr.querySelector('.ebill'), fi   = tr.querySelector('.efile'),
          fp   = tr.querySelector('.file-preview');
      var ledgerInput = tr.querySelector('.eledger');
      var et = sel?sel.value:'', dv = desc?desc.value.trim():'',
          av = parseFloat(amt?amt.value:0)||0, rv = rm?rm.value.trim():'',
          bv = bill?bill.checked:false,
          lv = ledgerInput ? ledgerInput.value : (LM[et]||'');
      if(!et && !dv && !av) return;
      if(!et)    { if(sel) sel.classList.add('ferr'); valid = false; return; }
      if(av <= 0){ if(amt) amt.classList.add('ferr'); valid = false; return; }
      if(!lv) {
        if(ledgerInput) ledgerInput.classList.add('ferr');
        else if(sel) sel.classList.add('ferr');
        valid = false;
        return;
      }
      var previewSrc = '', fileName = '', isPdf = false, billFile = null;
      if(bv) {
        if(fi && fi.files && fi.files.length) {
          var file = fi.files[0];
          if(file.size > 5*1024*1024) {
            fi.classList.add('req-file');
            frappe.show_alert({message:'Row '+(items.length+1)+': bill file exceeds 5 MB.', indicator:'red'}, 5);
            valid = false; return;
          }
          billFile = file;
          fileName = file.name;
          isPdf = file.type==='application/pdf' || fileName.toLowerCase().endsWith('.pdf');
          if(!isPdf) {
            var ti = fp?fp.querySelector('.thumb-img'):null;
            if(ti) previewSrc = ti.src;
          } else {
            previewSrc = URL.createObjectURL(file);
          }
        } else {
          if(fi) fi.classList.add('req-file');
          frappe.show_alert({message:'Row '+(items.length+1)+': attach a bill file.', indicator:'red'}, 5);
          valid = false; return;
        }
      }
      items.push({
        et:et, dv:dv, lv:lv, av:av, rv:rv,
        bv:bv, billFile:billFile,
        previewSrc:previewSrc, fileName:fileName, isPdf:isPdf
      });
    });

    var pb = q('#ePaidBy').value.trim(), ab = q('#eApprovedBy').value.trim(), pm = q('#ePayMode').value;
    if(!items.length) {
      frappe.msgprint({title:'No Items', message:'Add at least one item.', indicator:'red'});
      this.dataset.submitting = '0'; return;
    }
    var canonicalPaidBy = canonicalStaffValue(pb, paidByAllowedValues);
    var canonicalApprovedBy = canonicalStaffValue(ab, approvedByAllowedValues);

    if(!pb || !canonicalPaidBy) {
      q('#ePaidBy').classList.add('ferr');
      valid = false;
    } else {
      pb = canonicalPaidBy;
      q('#ePaidBy').value = canonicalPaidBy;
    }

    if(!ab || !canonicalApprovedBy) {
      q('#eApprovedBy').classList.add('ferr');
      valid = false;
    } else {
      ab = canonicalApprovedBy;
      q('#eApprovedBy').value = canonicalApprovedBy;
    }

    if(!pm) { q('#ePayMode').classList.add('ferr'); valid = false; }
    if(!valid) {
      frappe.msgprint({title:'Required Fields', message:'Fill all required fields and select valid staff names from the search suggestions.', indicator:'red'});
      this.dataset.submitting = '0'; return;
    }

    var total = 0; items.forEach(function(i) { total += i.av; });

    // ── Single company cash ledger + branch Cost Center ──────────────────
    // Cash account is ALWAYS 173001; branch separation is by Cost Center.
    var cashAcc = CASH_ACCOUNT;
    var costCenter = resolveCostCenter(branch);

    if(!costCenter) {
      this.dataset.submitting = '0';
      q('#eBranch').classList.add('ferr');
      frappe.msgprint({
        title: 'Cost Center Not Found',
        message: 'No Cost Center is mapped for branch <b>' + branch + '</b>.<br>Add it to COST_CENTER_MAP before submitting.',
        indicator: 'red'
      });
      return;
    }

    // Petty Cash Received should hit the single company cash ledger too
    items.forEach(function(i){
      if(i.et === 'Petty Cash Received') i.lv = cashAcc;
    });

    var btn = q('#eSubmitBtn');
    btn.disabled = true; btn.textContent = '⏳ Validating...';

    var allAccNames = items.map(function(i) { return i.lv; });
    allAccNames.push(cashAcc);

    apiValidateAccounts(allAccNames, function(found) {
      var groupAccs = found.filter(function(a) { return a.is_group; });
      var notFound  = allAccNames.filter(function(n) { return !found.find(function(a) { return a.name===n; }); });
      if(groupAccs.length || notFound.length) {
        btn.disabled = false; btn.dataset.submitting = '0';
        btn.textContent = '✅ Submit & Create Journal Entry';
        var msg = '';
        if(groupAccs.length) {
          msg += '<b>Group accounts (cannot post):</b><br>';
          groupAccs.forEach(function(a) { msg += '&#x2022; '+a.name+'<br>'; });
          msg += '<br>';
        }
        if(notFound.length) {
          msg += '<b>Accounts not found in CoA:</b><br>';
          notFound.forEach(function(n) {
            msg += '&#x2022; '+n+'<br>';
          });
          msg += '<br><b>Please check the exact account names in Chart of Accounts.</b>';
        }
        frappe.msgprint({title:'Account Error — Cannot Submit', message:msg, indicator:'red'});
        return;
      }

      btn.textContent = '⏳ Posting...';
      var accs = [];
      items.forEach(function(i) {
        accs.push({
          doctype:'Journal Entry Account',
          account: i.lv,
          cost_center: costCenter,
          debit_in_account_currency:  i.av,
          credit_in_account_currency: 0,
          user_remark: i.et + (i.dv?' - '+i.dv:'') + (i.rv?' | '+i.rv:'')
        });
      });
      accs.push({
        doctype:'Journal Entry Account',
        account: cashAcc,
        cost_center: costCenter,
        debit_in_account_currency:  0,
        credit_in_account_currency: total,
        user_remark: 'Expenditure | Branch:'+branch+' | '+pm+' | By:'+pb+' | Approved:'+ab
      });

      apiInsertJE({
        doctype:'Journal Entry', voucher_type:'Journal Entry',
        multi_currency:1, posting_date:edate,
        user_remark:'Expenditure | Branch:'+branch+' | '+pm+' | By:'+pb+' | Approved:'+ab,
        accounts:accs
      }, function(doc, err) {
        if(err || !doc) {
          frappe.msgprint({title:'JE Insert Error', message:(err&&err.responseText)||'Insert failed.', indicator:'red'});
          btn.disabled = false; btn.dataset.submitting = '0';
          btn.textContent = '✅ Submit & Create Journal Entry'; return;
        }
        var jn = doc.name;
        btn.textContent = '⏳ Uploading row bills...';

        apiUploadBillsPerRow(jn, items, function(billsOk, billsErr) {
          if(!billsOk) {
            frappe.msgprint({
              title:'Bill Upload Error',
              message:'The Journal Entry was not submitted because one or more row bills could not be saved separately.<br><br>' +
                ((billsErr && (billsErr.message || billsErr.responseText)) || 'Unknown bill upload error'),
              indicator:'red'
            });
            frappe.call({method:'frappe.client.delete', args:{doctype:'Journal Entry', name:jn}});
            btn.disabled = false;
            btn.dataset.submitting = '0';
            btn.textContent = '✅ Submit & Create Journal Entry';
            return;
          }

          btn.textContent = '⏳ Submitting...';
          apiSubmitJE(jn, function(ok, serr) {
            if(serr) {
              frappe.msgprint({title:'JE Saved — Submit Manually', message:'JE <b>'+jn+'</b> created. Open in ERPNext to submit.<br>Error: '+(serr.responseText||'unknown'), indicator:'orange'});
            }
            saved = true;
            q('#edocno').textContent = '';
            var sp = q('#estatus'); sp.className = 'esp posted'; sp.textContent = '● '+(ok?'Submitted':'Saved');
            btn.textContent = ok ? '✅ Submitted' : '⚠ Saved (submit manually)';
            btn.disabled = true;
            var jb = q('#eJeBox');
            jb.innerHTML =
              (ok?'✅':'⚠')+' <strong>Expenditure '+(ok?'Submitted':'Saved')+'!</strong><br>'+
              '🏢 <strong>'+branch+'</strong> | '+
              '📅 <strong>'+fmtDisp(edate)+'</strong> | '+
              '💰 <strong>'+fmtAmt(total)+'</strong> | '+
              '💳 <strong>'+pm+'</strong> | '+
              '👤 <strong>'+pb+'</strong> | ✔ <strong>'+ab+'</strong><br>'+
              '🏦 Cash A/c: <code style="font-size:12px;background:#dcfce7;padding:2px 6px;border-radius:3px">'+cashAcc+'</code> '+
              '&nbsp;🎯 Cost Center: <code style="font-size:12px;background:#dcfce7;padding:2px 6px;border-radius:3px">'+costCenter+'</code><br><br>'+
              '<button id="eNewEntryBtn" style="background:#16a34a;color:#fff;border:none;border-radius:5px;padding:7px 18px;font-size:14px;font-weight:700;cursor:pointer">+ New Entry</button>';
            jb.style.display = 'block';
            loadJEHistory(q('#eFilterFrom').value||edate, q('#eFilterTo').value||edate, currentUserBranch||q('#eFilterBranch').value||'', null);
            frappe.show_alert({message:'JE '+jn+(ok?' submitted':' saved')+' ✅', indicator:ok?'green':'orange'}, 3);

            // Refresh the full Web Page only after the Journal Entry is successfully submitted.
            // This clears the completed form and reloads the latest dashboard/history values.
            if(ok) {
              window.setTimeout(function() {
                window.location.reload();
              }, 1500);
            }
          });
        });
      });
    });
  });
});
  }

