          '<input type="text" class="life-select-search" autocomplete="off" placeholder="Search...">' +
        '</div>' +
        '<div class="life-select-options"></div>';
      document.body.appendChild(portal);
    }

    var searchWrap = portal.querySelector('.life-select-search-wrap');
    var searchInput = portal.querySelector('.life-select-search');
    var optionsHost = portal.querySelector('.life-select-options');

    var activeSelect = null;
    var activeButton = null;
    var activeOptions = [];

    function optionList(select) {
      return Array.prototype.slice.call(select.options || []);
    }

    function selectedLabel(select) {
      if (!select || select.selectedIndex < 0 || !select.options[select.selectedIndex]) {
        return '— Select —';
      }
      var opt = select.options[select.selectedIndex];
      return String(opt.textContent || opt.label || opt.value || '— Select —').trim();
    }

    function closePortal(restoreFocus) {
      portal.classList.remove('is-open');
      portal.style.display = 'none';

      if (activeButton) {
        activeButton.classList.remove('is-open');
        activeButton.setAttribute('aria-expanded', 'false');
      }

      var focusTarget = restoreFocus ? activeButton : null;
      activeSelect = null;
      activeButton = null;
      activeOptions = [];
      searchInput.value = '';

      if (focusTarget) {
        try { focusTarget.focus(); } catch (e) {}
      }
    }

    function positionPortal(button) {
      if (!button) return;
      var r = button.getBoundingClientRect();
      var viewportH = window.innerHeight || document.documentElement.clientHeight || 800;
      var gap = 5;
      var desiredMax = 330;
      var below = viewportH - r.bottom - gap;
      var above = r.top - gap;
      var openAbove = below < 190 && above > below;
      var available = Math.max(120, Math.min(desiredMax, openAbove ? above : below));

      portal.style.left = Math.max(6, r.left) + 'px';
      portal.style.width = Math.max(180, r.width) + 'px';
      portal.style.maxWidth = Math.max(180, Math.min(r.width, (window.innerWidth || 1200) - 12)) + 'px';

      if (openAbove) {
        portal.style.top = 'auto';
        portal.style.bottom = Math.max(6, viewportH - r.top + gap) + 'px';
      } else {
        portal.style.bottom = 'auto';
        portal.style.top = Math.max(6, r.bottom + gap) + 'px';
      }

      optionsHost.style.maxHeight = Math.max(90, available - (searchWrap.hidden ? 10 : 58)) + 'px';
    }

    function renderPortal(filterText) {
      if (!activeSelect) return;

      var query = String(filterText || '').trim().toLowerCase();
      optionsHost.innerHTML = '';

      var visible = activeOptions.filter(function(opt) {
        if (!query) return true;
        var txt = String(opt.textContent || opt.label || opt.value || '').toLowerCase();
        var val = String(opt.value || '').toLowerCase();
        return txt.indexOf(query) !== -1 || val.indexOf(query) !== -1;
      });

      if (!visible.length) {
        optionsHost.innerHTML = '<div class="life-select-empty">No matching option</div>';
        return;
      }

      visible.forEach(function(opt) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className =
          'life-select-option' +
          (!opt.value ? ' is-placeholder' : '') +
          (String(opt.value) === String(activeSelect.value) ? ' is-selected' : '');
        btn.dataset.value = opt.value;
        btn.setAttribute('role', 'option');
        btn.setAttribute(
          'aria-selected',
          String(opt.value) === String(activeSelect.value) ? 'true' : 'false'
        );
        btn.textContent = String(opt.textContent || opt.label || opt.value || '').trim();

        btn.addEventListener('click', function(e) {
          e.preventDefault();
          e.stopPropagation();

          if (!activeSelect) return;

          var select = activeSelect;
          select.value = btn.dataset.value;
          select.dispatchEvent(new Event('change', { bubbles: true }));
          sync(select);
          closePortal(true);
        });

        optionsHost.appendChild(btn);
      });
    }

    function openPortal(select, button) {
      if (!select || !button || select.disabled) return;

      if (activeSelect === select && portal.classList.contains('is-open')) {
        closePortal(false);
        return;
      }

      if (activeButton) {
        activeButton.classList.remove('is-open');
        activeButton.setAttribute('aria-expanded', 'false');
      }

      activeSelect = select;
      activeButton = button;
      activeOptions = optionList(select);

