      if (e.key === 'Escape' && portal.classList.contains('is-open')) {
        closePortal(true);
      }
    });

    window.addEventListener('resize', function() {
      if (portal.classList.contains('is-open') && activeButton) {
        positionPortal(activeButton);
      }
    });

    var scrollFrame = 0;
    window.addEventListener('scroll', function(e) {
      if (!portal.classList.contains('is-open')) return;

      /* Scroll inside the staff option list: leave it open. */
      if (e && e.target && portal.contains(e.target)) return;

      if (!activeButton) return;

      if (scrollFrame) {
        window.cancelAnimationFrame(scrollFrame);
      }

      scrollFrame = window.requestAnimationFrame(function() {
        scrollFrame = 0;

        if (!portal.classList.contains('is-open') || !activeButton) return;

        var rect = activeButton.getBoundingClientRect();
        var vh = window.innerHeight || document.documentElement.clientHeight || 800;
        var vw = window.innerWidth || document.documentElement.clientWidth || 1200;

        if (
          rect.bottom < 0 ||
          rect.top > vh ||
          rect.right < 0 ||
          rect.left > vw
        ) {
          closePortal(false);
          return;
        }

        positionPortal(activeButton);
      });
    }, true);

    /* The original page changes .value directly in resetForm().
       Keep the visible staff buttons synchronized with those direct assignments. */
    var lastPaidValue = paidInput.value;
    var lastApprovedValue = approvedInput.value;
    var lastPaidDisabled = paidInput.disabled;
    var lastApprovedDisabled = approvedInput.disabled;
    var lastPaidPlaceholder = paidInput.placeholder;
    var lastApprovedPlaceholder = approvedInput.placeholder;

    window.setInterval(function() {
      if (
        lastPaidValue !== paidInput.value ||
        lastPaidDisabled !== paidInput.disabled ||
        lastPaidPlaceholder !== paidInput.placeholder
      ) {
        lastPaidValue = paidInput.value;
        lastPaidDisabled = paidInput.disabled;
        lastPaidPlaceholder = paidInput.placeholder;
        syncField(paidInput);
      }

      if (
        lastApprovedValue !== approvedInput.value ||
        lastApprovedDisabled !== approvedInput.disabled ||
        lastApprovedPlaceholder !== approvedInput.placeholder
      ) {
        lastApprovedValue = approvedInput.value;
        lastApprovedDisabled = approvedInput.disabled;
        lastApprovedPlaceholder = approvedInput.placeholder;
        syncField(approvedInput);
      }
    }, 250);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootStaffDropdowns, {once:true});
  } else {
    window.setTimeout(bootStaffDropdowns, 0);
  }
})();
